// Reject a universal enterprise ontology; bind semantic definitions strictly to task contracts at actuation boundaries.
function execute_governed_action(agent_intent, agent_token, tool_id):
  // 1. Resolve semantic dialect per tool rather than expecting CRM and warehouse to ever agree globally.
  contract = semantic_registry.resolve(tool_id, agent_intent.target_concept)
  // 2. Synthesize runtime row and field predicates from the caller identity before tool execution.
  entitlements = policy_engine.compile_predicates(agent_token.subject, contract.governance_rules)
  // 3. Fail closed if the target tool cannot guarantee the required filter granularity.
  if not tool_adapter(tool_id).can_enforce(entitlements):
    throw SecurityDemotionFault(tool_id, entitlements)
  // 4. Bind action to an ephemeral, deterministic snapshot instead of broad conversational context.
  action_scope = tool_adapter(tool_id).bind_ephemeral_view(contract.query_logic, entitlements)
  // 5. Execute statelessly so transport spec revisions do not break the underlying semantic contracts.
  return tool_adapter(tool_id).invoke(agent_intent.action, action_scope)
